 "concept", "title": "Unions"}, {"id": "cf6ca447-9e22-4e0a-a18f-bbb03a8824db", "type": "concept", "title": "Monopsony"}, {"id": "5c062f10-e81c-4efb-a69c-199526975ee2", "type": "concept", "title": "Wage discrimination"}], "description": "Labor markets connect micro theory to inequality, policy, and institutions."}]}, {"id": "be75e9ab-697b-4080-a5fe-05ee26d90b48", "type": "topic", "title": "Externalities and Public Goods", "description": "Study market failures where private incentives diverge from social costs and benefits.", "children": [{"id": "c627a94b-3e4c-4065-ac00-08f9254655bb", "type": "subtopic", "title": "Externalities", "children": [{"id": "50bbc89a-496c-4498-a288-c8ff77824529", "type": "concept", "title": "Negative externalities"}, {"id": "78b58145-ca45-44ef-8c9a-0b162078b18c", "type": "concept", "title": "Positive externalities"}, {"id": "c9df506d-cafb-4f8e-ba74-e78594fb569e", "type": "concept", "title": "Marginal social cost"}, {"id": "dfb28ef4-1781-4440-b3c9-343f4480d845", "type": "concept", "title": "Marginal social benefit"}], "description": "Externalities occur when private decisions impose costs or benefits on others."}, {"id": "f8fd1331-119d-4084-8ec1-a936b8b16bc1", "type": "subtopic", "title": "Policy tools", "children": [{"id": "e22fda9a-c0db-4cbf-845c-38c32459b1c1", "type": "concept", "title": "Pigouvian taxes"}, {"id": "3b0a7b2e-79ee-40b9-8c0b-eb4f3c205b58", "type": "concept", "title": "Subsidies"}, {"id": "2d5f4f32-dce0-403c-91d8-69e0ec6e4899", "type": "concept", "title": "Tradable permits"}, {"id": "1424831e-a42a-4801-9fba-e9c9c6e8af2d", "type": "concept", "title": "Regulation"}], "description": "Policy can align private incentives with social outcomes."}, {"id": "23ea5366-1aa3-46fb-8074-da0e7074e60b", "type": "subtopic", "title": "Public goods and common resources", "children": [{"id": "f52b3e9f-189a-4361-934b-f21b823dde9b", "type": "concept", "title": "Nonrivalry"}, {"id": "10b6abe8-0cc4-4be4-b865-bfb4e726a199", "type": "concept", "title": "