", "title": "Incentives"}, {"id": "d612dbf8-d995-4bc7-b5e0-5f24c7c96e91", "type": "concept", "title": "Assumptions"}, {"id": "cc730bf6-df36-4e82-a7c2-a90356d0d0df", "type": "concept", "title": "Positive analysis"}, {"id": "ede8947d-209f-4daf-9666-894bb31b7cec", "type": "concept", "title": "Normative analysis"}], "description": "Models simplify reality so students can reason clearly about incentives and outcomes."}]}, {"id": "60c71dce-400d-4a36-9b86-a67cfd702712", "type": "topic", "title": "Supply, Demand, and Market Equilibrium", "description": "Use the central market model to explain prices, quantities, shortages, surpluses, and comparative statics.", "children": [{"id": "f1192487-69bc-4f2b-a435-e164f0b0e94a", "type": "subtopic", "title": "Demand", "children": [{"id": "9af169e8-980e-4a62-92eb-a3149569ee28", "type": "concept", "title": "Law of demand"}, {"id": "e3f483ed-f6a0-4581-9941-bcf88b338a66", "type": "concept", "title": "Demand curve"}, {"id": "cdd84c3e-d1a0-4012-85dd-79d682c35684", "type": "concept", "title": "Shifts in demand"}, {"id": "85f8502d-66e3-49d3-8715-b53800ad3c49", "type": "concept", "title": "Substitutes and complements"}], "description": "Demand shows how buyers respond to prices and other market conditions."}, {"id": "85d7bc5f-b9f1-48ef-ad4a-39ed38a56e16", "type": "subtopic", "title": "Supply", "children": [{"id": "b583a2ec-2615-403d-af10-cb203a02d516", "type": "concept", "title": "Law of supply"}, {"id": "1d8d8759-4cbf-46c9-9899-144099aa4fe7", "type": "concept", "title": "Supply curve"}, {"id": "169003a8-681c-45aa-bf3c-d1bac398f857", "type": "concept", "title": "Shifts in supply"}, {"id": "5656d5bc-4f15-4e50-adbe-99aa6337889a", "type": "concept", "title": "Input costs and technology"}], "description": "Supply shows how sellers respond to prices, costs, and technology."}, {"id": "5138356a-1a8e-463a-8320-02eda66dec03", "type": "subtopic", "title": "Equilibrium and comparative statics", "children": [{"id": "54f55a3d-b892-48c7-8f1b-d161f20c5d75", 